  topLeft: cc.v2(0, 0),
  topRight: cc.v2(0, 0),
  top: cc.v2(0, 0),
  bottomLeft: cc.v2(0, 0),
  bottomRight: cc.v2(0, 0),
  bottom: cc.v2(0, 0),
